function normalized(string $value):string{$value=iconv('UTF-8','ASCII//TRANSLIT//IGNORE',$value)?:$value;return strtoupper($value);}
function classify(string $value):?string{$v=normalized($value);if(str_contains($v,'AVCB')||str_contains($v,'VISTORIA DO CORPO DE BOMBEIROS'))return 'AVCB (Corpo de Bombeiros)';if(str_contains($v,'PGRSS'))return 'PGRSS (Resíduos de Serviços de Saúde)';if(str_contains($v,'PGRS'))return 'PGRS (Plano de Gerenciamento de Resíduos Sólidos)';if(str_contains($v,'INVENTARIO'))return 'Inventário de Resíduos';if(str_contains($v,'RAPP'))return 'RAPP (Relatório Anual de Atividades Potencialmente Poluidoras)';if(str_contains($v,'CADRI'))return 'CADRI / Autorização para Resíduos';if(str_contains($v,'CADASTRO TECNICO')||str_contains($v,'CADASTRO TECNICO FEDERAL'))return 'Cadastro Técnico Federal (IBAMA)';if(str_contains($v,'IBAMA')&&str_contains($v,'CADASTRO'))return 'Cadastro Técnico Federal (IBAMA)';if(str_contains($v,'ANVISA')&&preg_match('/\bAFE\b/',$v))return 'ANVISA - AFE';if(str_contains($v,'ANVISA')&&(str_contains($v,' AE ')||str_contains($v,'AUTORIZACAO ESPECIAL')))return 'ANVISA - AE';if(str_contains($v,'OUTORGA'))return 'Outorga';if(str_contains($v,'EFLUENTE')||str_contains($v,'LANCAMENTO'))return 'Autorização para Efluentes';if(str_contains($v,'MAPA DE PRODUTOS')||str_contains($v,'POLICIA CIVIL'))return 'Mapa de Produtos Controlados';if(str_contains($v,'EXERCITO')||str_contains($v,'CERTIFICADO DE REGISTRO'))return 'Certificado de Registro - Exército';if(str_contains($v,'OCUPACAO DO SOLO'))return 'Uso e Ocupação do Solo';if(str_contains($v,'POLICIA FEDERAL'))return 'Certificado de Licença - Polícia Federal';if(str_contains($v,'INSTALACAO'))return 'Licença Ambiental de Instalação';if(str_contains($v,'OPERACAO'))return 'Licença Ambiental de Operação';if(str_contains($v,'LICENCA AMBIENTAL'))return 'Licença Ambiental';if(str_contains($v,'ALVAR')||str_contains($v,'FUNCIONAMENTO'))return 'Alvará e Licença de Funcionamento';return null;}
$summary=[];
foreach($databases as $database){$pdo=GreenPortalDatabase::connect($env,$database,'GPT');$insert=$pdo->prepare('INSERT INTO li_tipos_documentos(DSCTIPODOCUMENTO,ATIVO,ORDEM) VALUES(?,1,?) ON DUPLICATE KEY UPDATE ATIVO=1,ORDEM=VALUES(ORDEM)');foreach($types as [$name,$order])$insert->execute([$name,$order]);$ids=[];$q=$pdo->query('SELECT CODTIPODOCUMENTO,DSCTIPODOCUMENTO FROM li_tipos_documentos');foreach($q as $row)$ids[$row['DSCTIPODOCUMENTO']]=(int)$row['CODTIPODOCUMENTO'];$default=$ids['Não classificado'];$updated=0;$ambiguous=0;$q=$pdo->query('SELECT CODLICENCA,DSCLICENCA,CODTIPODOCUMENTO FROM li_licencas');$update=$pdo->prepare('UPDATE li_licencas SET CODTIPODOCUMENTO=? WHERE CODLICENCA=? AND (CODTIPODOCUMENTO IS NULL OR CODTIPODOCUMENTO=?)');foreach($q as $row){$classification=classify((string)$row['DSCLICENCA']);if($classification!==null&&isset($ids[$classification])){$update->execute([$ids[$classification],(int)$row['CODLICENCA'],$default]);$updated+=(int)$update->rowCount();}else{$ambiguous++;}}$parent=(int)$pdo->query("SELECT codmenu FROM menus WHERE codigo='MODULO_LEGAL' LIMIT 1")->fetchColumn();$menu=$pdo->prepare("INSERT INTO menus(codmenu_pai,modulo,codigo,label,label_pt,label_en,label_es,url,nivel,ordem,ativo) VALUES(?,?,?,?,?,?,?,?,?,?,1) ON DUPLICATE KEY UPDATE codmenu_pai=VALUES(codmenu_pai),modulo=VALUES(modulo),label=VALUES(label),label_pt=VALUES(label_pt),label_en=VALUES(label_en),label_es=VALUES(label_es),url=VALUES(url),nivel=VALUES(nivel),ordem=VALUES(ordem),ativo=1");$menu->execute([$parent,'MANUTENCAO_LEGAL','TIPOS_DOCUMENTOS_LICENCAS','Tipos documentais de licenças','Tipos documentais de licenças','License document types','Tipos documentales de licencias','/principal/manutencaolegal_tiposdocumentos.php',2,4]);$menuId=(int)$pdo->query("SELECT codmenu FROM menus WHERE codigo='TIPOS_DOCUMENTOS_LICENCAS' LIMIT 1")->fetchColumn();foreach(['ADMINISTRADOR'] as $profileCode){$profile=(int)($st=$pdo->prepare('SELECT codperfil FROM perfis WHERE codigo=? AND ativo=1 LIMIT 1'))->execute([$profileCode])?:0;$st=$pdo->prepare('SELECT codperfil FROM perfis WHERE codigo=? AND ativo=1 LIMIT 1');$st->execute([$profileCode]);$profile=(int)$st->fetchColumn();if($profile){$pm=$pdo->prepare('INSERT INTO perfil_menus(codperfil,codmenu,pode_incluir,pode_visualizar,pode_editar,pode_excluir,pode_exportar_excel,pode_gerar_pdf) VALUES(?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE pode_incluir=VALUES(pode_incluir),pode_visualizar=VALUES(pode_visualizar),pode_editar=VALUES(pode_editar),pode_excluir=VALUES(pode_excluir),pode_exportar_excel=VALUES(pode_exportar_excel),pode_gerar_pdf=VALUES(pode_gerar_pdf)');$pm->execute([$profile,$menuId,1,1,1,1,1,1]);$pm2=$pdo->prepare('INSERT INTO permissoes(codperfil,codmenu,pode_incluir,pode_visualizar,pode_editar,pode_excluir,pode_exportar_excel,pode_gerar_pdf) VALUES(?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE pode_incluir=VALUES(pode_incluir),pode_visualizar=VALUES(pode_visualizar),pode_editar=VALUES(pode_editar),pode_excluir=VALUES(pode_excluir),pode_exportar_excel=VALUES(pode_exportar_excel),pode_gerar_pdf=VALUES(pode_gerar_pdf)');$pm2->execute([$profile,$menuId,1,1,1,1,1,1]);}}
$pdo->prepare("INSERT INTO registros_migracao(codigo_migracao,origem,destino,tipo,versao,status,quantidade_registros,iniciada_em,concluida_em,detalhes) VALUES('GREEN_LICENSE_TYPES_CATALOG_227','li_licencas','li_tipos_documentos;menus','DADOS','4.0.1','CONCLUIDA',?,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,?) ON DUPLICATE KEY UPDATE status='CONCLUIDA',quantidade_registros=VALUES(quantidade_registros),concluida_em=CURRENT_TIMESTAMP,detalhes=VALUES(detalhes)")->execute([(int)$pdo->query('SELECT COUNT(*) FROM li_licencas')->fetchColumn(),json_encode(['tipos'=>count($types),'classificadas'=>$updated,'pendentes_revisao'=>$ambiguous],JSON_UNESCAPED_UNICODE)]);$summary[$database]=['tipos'=>(int)$pdo->query('SELECT COUNT(*) FROM li_tipos_documentos WHERE ATIVO=1')->fetchColumn(),'licencas_classificadas'=>$updated,'pendentes_revisao'=>$ambiguous,'menu'=>$menuId];}
